insert into public.marketing_resources
  (slug, title, description, category, read_minutes, related_href, related_label, sections, is_published, sort_order)
values
('weight-loss-medication-questions-for-your-doctor', 'Weight-loss medication: what to ask your doctor before you start', 'What these medicines actually do, who they''re usually considered for, and the questions worth taking to that conversation.', 'Weight', 5, '/obesity', 'The Tarragon weight programme', '[{"heading":"What these medicines actually do","paragraphs":["The weight-loss medications getting attention right now work mainly by slowing digestion and quieting appetite signals in the brain, so people eat less without fighting constant hunger. They are prescription medicines, taken under medical supervision, not a supplement you start on your own.","They work best alongside the same lifestyle changes that already help everyone, not instead of them. Food, movement and sleep still matter once you''re on one; the medicine makes those changes easier to sustain, not unnecessary."]},{"heading":"Who they''re usually considered for","paragraphs":["They are typically considered for people with a BMI in the obesity range, or an overweight BMI alongside a related condition like raised blood pressure or blood sugar, after a proper assessment of history and risk. They are not usually a first answer for someone who wants to lose a few kilograms for an event."]},{"heading":"Questions worth taking to that conversation","paragraphs":["Am I actually a candidate, based on my BMI and health history, not just what I''d like? What side effects are common, and which ones mean I should call back sooner rather than wait? What happens to my weight if I stop the medicine later? How will this be monitored over time, and what does it cost to continue, not just to start?"]},{"heading":"Where Tarragon fits today","paragraphs":["Tarragon''s weight programme is lifestyle-managed: weight and waist tracking, a personalised plan, monitoring of related conditions like blood pressure and sugar, and regular doctor review. We don''t currently prescribe weight-loss medication ourselves, and we''d rather say that plainly than overpromise. Where a doctor review suggests a medical conversation about medication is worth having, that''s flagged so you can pursue it, informed rather than guessing."]}]'::jsonb, true, 52),
('finding-healthy-food-on-any-budget', 'Finding healthy food in any Nigerian market, on any budget', 'You don''t need imported diet products. Local markets already have what a healthier plate needs, if you know what to look for.', 'Weight', 4, '/obesity', 'The Tarragon weight programme', '[{"heading":"Healthy doesn''t mean imported","paragraphs":["Vegetables like ugu, waterleaf and garden egg, beans, fresh fish, and unripe plantain are already close to what any healthy-eating guide recommends. None of it comes in a branded ''diet'' package, and none of it needs to."]},{"heading":"Shop the fresh sections, not the packaged aisle","paragraphs":["Produce, fish and meat sections tend to be both fresher and, per meal, cheaper than heavily processed or packaged alternatives once you account for how far a home-cooked pot of soup stretches. Buying what''s in season usually costs less and tastes better too."]},{"heading":"Protein and fibre stretch further than you''d think","paragraphs":["Beans, eggs and fish are usually cheaper sources of protein than red meat, and fibre-rich vegetables bulk out a plate cheaply while keeping you fuller for longer. A bigger vegetable-and-protein base with a smaller starch portion often costs about the same as the reverse."]},{"heading":"Small swaps that don''t cost extra","paragraphs":["Water or unsweetened zobo instead of a sugary soft drink, a slightly smaller rice or eba portion with beans added in, grilled instead of deep-fried where the price is similar. None of these require a bigger food budget, just a different way of filling the same plate."]}]'::jsonb, true, 53),
('managing-triggers-that-lead-to-overeating', 'Managing the triggers that lead to overeating', 'Stress, boredom, and habit drive most overeating, not hunger. Recognising the trigger is the first real step.', 'Weight', 4, '/obesity', 'The Tarragon weight programme', '[{"heading":"Most overeating isn''t really about hunger","paragraphs":["Eating in front of a screen, finishing a plate out of habit rather than appetite, or reaching for food when stressed or bored, all feel like hunger in the moment but usually aren''t. Learning to tell the difference between physical hunger and an emotional or habitual trigger is the useful skill, not willpower."]},{"heading":"Common triggers worth noticing","paragraphs":["Stress and anxiety, boredom or understimulation, poor sleep (which genuinely raises appetite hormones the next day), social pressure to finish what''s served, and simply eating on autopilot while distracted are the ones that come up most often. None of them mean anything is wrong with you; they''re just worth noticing."]},{"heading":"What actually helps, in the moment","paragraphs":["A short pause before eating, just asking ''am I actually hungry, or is something else going on?'', catches a surprising amount. Keeping an easy, ready alternative on hand helps too. Where the trigger is stress, addressing that directly, even a short walk, works better than food ever will at actually resolving it."]},{"heading":"When to loop in your care team","paragraphs":["If eating feels genuinely out of your control, or seems tied to low mood that''s lasted more than a couple of weeks, that''s worth raising with a doctor rather than treating as a personal failing. Addressing it is part of good weight care, not a separate, lesser concern."]}]'::jsonb, true, 54)
